package com.greytest.benchmark.customer;

import com.greytest.benchmark.common.DomainException;
import com.greytest.benchmark.common.NotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

/**
 * Quản lý trạng thái, hạng thành viên và lịch sử chi tiêu của khách hàng.
 */
@Service
public class CustomerService {

    private final CustomerRepository repository;

    public CustomerService(CustomerRepository repository) {
        this.repository = repository;
    }

    @Transactional
    public Customer register(CustomerRequest request) {
        String email = request.email().trim().toLowerCase();
        if (repository.findByEmailIgnoreCase(email).isPresent()) {
            throw new DomainException("Email already registered");
        }
        Customer customer = new Customer();
        customer.setEmail(email);
        customer.setFullName(request.fullName().trim());
        customer.setTier("STANDARD");
        customer.setActive(true);
        try {
            return repository.save(customer);
        } catch (DataIntegrityViolationException exception) {
            throw new DomainException("Email already registered");
        }
    }

    @Transactional(readOnly = true)
    public Customer requireActive(Long customerId) {
        Customer customer = repository.findById(customerId).orElseThrow(() -> new NotFoundException("Customer", customerId));
        if (!customer.isActive()) {
            throw new DomainException("Customer is inactive");
        }
        return customer;
    }

    @Transactional
    public void addSpend(Long customerId, BigDecimal amount) {
        Customer customer = requireActive(customerId);
        customer.setLifetimeSpend(customer.getLifetimeSpend().add(amount));
        BigDecimal spend = customer.getLifetimeSpend();
        customer.setTier(spend.compareTo(new BigDecimal("5000")) >= 0 ? "PLATINUM" : spend.compareTo(new BigDecimal("1000")) >= 0 ? "GOLD" : "STANDARD");
        repository.save(customer);
    }
}

